// Replaced at build time — see `define` in vite.config.ts.

/** When this build was made, as an ISO timestamp. */
declare const __BUILD_TIME__: string;
/** Short commit of the family repository, `-dirty` with uncommitted edits; empty for the sample. */
declare const __FAMILY_COMMIT__: string;

/** Whether countries get their flag — off with STAMMBAUM_FLAGS=off at build time. */
declare const __FLAGS__: boolean;
